}

def find_index(nums, target):
    try:
        return nums.index(target)         # a linear search; raises ValueError when missing
    except ValueError:
        return -1

int findIndex(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {   // int[] has no indexOf (a List does)
        if (nums[i] == target) return i;
    }
    return -1;
}

int findIndex(vector<int>& nums, int target) {
    auto it = find(nums.begin(), nums.end(), target);   // a linear search
    return it == nums.end() ? -1 : it - nums.begin();
}
